        if (columnName == null || !COLUMN_NAME_PATTERN.matcher(columnName).matches()) {
            throw new IllegalArgumentException("Invalid column name. Must be a valid SQL identifier.");
        }
        if (columnType == null || !COLUMN_TYPE_PATTERN.matcher(columnType).matches()) {
            throw new IllegalArgumentException("Invalid column type. Contains unsupported characters.");
        }

        String sql = "ALTER TABLE products ADD COLUMN " + columnName + " " + columnType;

        try {
            jdbcTemplate.execute(sql);
        } catch (Exception e) {
            throw new RuntimeException("Failed to add column '" + columnName + "' to products table.", e);
        }
    }
